<script setup lang="ts">
import type { PurchaseProductInput, ShopProductDraft } from '../api/commerce'
import type { ShopController } from '../model/useCommerce'
import { computed, reactive, shallowRef, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { formatCommerceAmount } from '../api/commerce'
const props = defineProps<{ controller: ShopController }>()
const emit = defineEmits<{ load: [id: string], save: [draft: ShopProductDraft], purchase: [input: PurchaseProductInput] }>()
const { t } = useI18n()
const lookupId = shallowRef(''); const draft = reactive({ productId: '', name: '', description: '', enabled: true, priceAmount: '0', stockRemaining: '', perPlayerLimit: '', rewardPackageId: '', sortOrder: 0 }); const buyer = reactive({ crossplatformId: '', expectedEntityId: 0, expectedWorldId: '', quantity: 1 })
watch(() => props.controller.product.value, (value) => { if (value) Object.assign(draft, { productId: value.productId, name: value.name, description: value.description, enabled: value.enabled, priceAmount: value.priceAmount.toString(), stockRemaining: value.stockRemaining?.toString() ?? '', perPlayerLimit: value.perPlayerLimit?.toString() ?? '', rewardPackageId: value.rewardPackageId, sortOrder: value.sortOrder }) }, { immediate: true })
const valid = computed(() => draft.productId.trim() !== '' && draft.name.trim() !== '' && /^\d+$/.test(draft.priceAmount) && draft.rewardPackageId.trim() !== '')
function create() { Object.assign(draft, { productId: lookupId.value.trim(), name: '', description: '', enabled: true, priceAmount: '0', stockRemaining: '', perPlayerLimit: '', rewardPackageId: '', sortOrder: 0 }) }
function save() { if (valid.value) emit('save', { productId: draft.productId.trim(), name: draft.name.trim(), description: draft.description, enabled: draft.enabled, priceAmount: BigInt(draft.priceAmount), stockRemaining: draft.stockRemaining === '' ? null : BigInt(draft.stockRemaining), perPlayerLimit: draft.perPlayerLimit === '' ? null : Number(draft.perPlayerLimit), rewardPackageId: draft.rewardPackageId.trim(), sortOrder: draft.sortOrder }) }
function purchase() { emit('purchase', { productId: draft.productId, ...buyer, clientRequestKey: crypto.randomUUID() }) }
</script>
<template><UDashboardPanel id="shop-products"><template #header><UDashboardNavbar :title="t('commerce.shop.title')"><template #leading><UDashboardSidebarCollapse /></template></UDashboardNavbar></template><template #body><UContainer class="space-y-5 py-5"><UAlert v-if="props.controller.errorCode.value" color="error" :title="t('commerce.shop.operationIncomplete')" :description="props.controller.errorCode.value" /><UAlert v-if="props.controller.purchase.value?.state === 'PendingReconciliation'" color="warning" :title="t('commerce.shop.reconciliation.title')" :description="t('commerce.shop.reconciliation.description')" /><UCard><div class="grid gap-3 md:grid-cols-[minmax(0,1fr)_auto_auto] md:items-end"><UFormField :label="t('commerce.shop.productId')"><UInput v-model="lookupId" class="w-full" /></UFormField><UButton color="neutral" :label="t('commerce.common.load')" variant="outline" @click="emit('load', lookupId.trim())" /><UButton :label="t('commerce.common.createWithId')" variant="soft" @click="create" /></div></UCard><UCard v-if="draft.productId"><template #header><h2 class="font-semibold">{{ draft.productId }}</h2></template><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><UFormField :label="t('commerce.common.name')"><UInput v-model="draft.name" class="w-full" /></UFormField><UFormField :label="t('commerce.common.rewardPackageId')"><UInput v-model="draft.rewardPackageId" class="w-full" /></UFormField><UFormField :label="t('commerce.shop.price')"><UInput v-model="draft.priceAmount" class="w-full" inputmode="numeric" /></UFormField><UFormField :label="t('commerce.shop.stock')"><UInput v-model="draft.stockRemaining" class="w-full" inputmode="numeric" /></UFormField><UFormField :label="t('commerce.common.perPlayerLimit')"><UInput v-model="draft.perPlayerLimit" class="w-full" inputmode="numeric" /></UFormField><UFormField :label="t('commerce.common.sortOrder')"><UInput v-model.number="draft.sortOrder" class="w-full" type="number" /></UFormField><UFormField class="md:col-span-2 xl:col-span-3" :label="t('commerce.common.description')"><UTextarea v-model="draft.description" class="w-full" /></UFormField><UCheckbox v-model="draft.enabled" :label="t('commerce.shop.enabled')" /></div><template #footer><div class="flex justify-end"><UButton :label="t('commerce.shop.save')" :disabled="!valid" :loading="props.controller.isMutating.value" @click="save" /></div></template></UCard><UCard v-if="draft.productId"><template #header><div><h2 class="font-semibold">{{ t('commerce.shop.purchase.title') }}</h2><p class="text-sm text-muted">{{ t('commerce.shop.purchase.priceNotice', { price: /^\d+$/.test(draft.priceAmount) ? formatCommerceAmount(BigInt(draft.priceAmount)) : '-' }) }}</p></div></template><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><UFormField :label="t('commerce.common.playerId')"><UInput v-model="buyer.crossplatformId" class="w-full" /></UFormField><UFormField :label="t('commerce.common.entityId')"><UInput v-model.number="buyer.expectedEntityId" class="w-full" type="number" /></UFormField><UFormField :label="t('commerce.common.worldId')"><UInput v-model="buyer.expectedWorldId" class="w-full" /></UFormField><UFormField :label="t('commerce.common.quantity')"><UInput v-model.number="buyer.quantity" class="w-full" min="1" type="number" /></UFormField></div><template #footer><div class="flex justify-end"><UButton :label="t('commerce.shop.purchase.submit')" :disabled="!buyer.crossplatformId || !buyer.expectedWorldId || props.controller.isMutating.value" @click="purchase" /></div></template></UCard></UContainer></template></UDashboardPanel></template>
